using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — knows about any public type.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣  GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣  TryGetTypeInfo<T>() — probe without throwing.
//     With the default resolver every public type resolves, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person> → found ({found!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person> → not available");

// Now use a *custom* resolver that only knows about Person.
// Asking for int will return false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Only keep metadata for Person; wipe everything else.
            if (ti.Type != typeof(Person))
                ti.Kind = JsonTypeInfoKind.None;   // mark as unusable
        })
};

// Force resolution so TryGetTypeInfo can query the cache.
limited.TryGetTypeInfo<Person>(out _);

if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
    Console.WriteLine($"TryGetTypeInfo<int> → found ({intInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<int> → not available (no exception!)");

public record Person(string Name, int Age);

